const { useState } = React;

function App() {
  const [amount, setAmount] = useState("");
  const [rate, setRate] = useState("");
  const [term, setTerm] = useState("12");
  const [monthlyPayment, setMonthlyPayment] = useState(null);
  const [error, setError] = useState("");

  // Calculate monthly payment using formula for loan amortization
  // P = (r*PV) / (1 - (1 + r)^-n)
  // r = monthly interest rate, PV = loan amount, n = number of months
  function calculatePayment() {
    setError("");
    setMonthlyPayment(null);

    if (amount.trim() === "" || rate.trim() === "") {
      setError("Please enter both loan amount and interest rate.");
      return;
    }

    const principal = parseFloat(amount);
    const annualRate = parseFloat(rate);
    const months = parseInt(term, 10);

    if (isNaN(principal) || principal <= 0) {
      setError("Loan amount must be a positive number.");
      return;
    }
    if (isNaN(annualRate) || annualRate < 0) {
      setError("Interest rate must be a non-negative number.");
      return;
    }

    const monthlyRate = annualRate / 100 / 12;

    let payment;
    if (monthlyRate === 0) {
      payment = principal / months;
    } else {
      payment = (monthlyRate * principal) / (1 - Math.pow(1 + monthlyRate, -months));
    }

    setMonthlyPayment(payment.toFixed(2));
  }

  return (
    <main style={{
      maxWidth: 320,
      margin: "2rem auto",
      fontFamily: "Arial, sans-serif",
      color: "#222"
    }}>
      <h2 style={{ marginBottom: "1rem" }}>Loan calculator</h2>
      <form
        onSubmit={e => {
          e.preventDefault();
          calculatePayment();
        }}
        style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}
        noValidate
      >
        <label htmlFor="amount" style={{ fontSize: "0.9rem" }}>
          Loan amount
        </label>
        <input
          id="amount"
          type="number"
          min="0"
          step="any"
          value={amount}
          onChange={e => setAmount(e.target.value)}
          placeholder=""
          style={{
            padding: "0.5rem",
            fontSize: "1rem",
            borderRadius: 4,
            border: "1.5px solid #999"
          }}
          aria-describedby="amount-error"
        />

        <label htmlFor="rate" style={{ fontSize: "0.9rem" }}>
          Interest rate
        </label>
        <input
          id="rate"
          type="number"
          min="0"
          step="any"
          value={rate}
          onChange={e => setRate(e.target.value)}
          placeholder=""
          style={{
            padding: "0.5rem",
            fontSize: "1rem",
            borderRadius: 4,
            border: "1.5px solid #999"
          }}
          aria-describedby="rate-error"
        />

        <label htmlFor="term" style={{ fontSize: "0.9rem" }}>
          Term
        </label>
        <select
          id="term"
          value={term}
          onChange={e => setTerm(e.target.value)}
          style={{
            padding: "0.5rem",
            fontSize: "1rem",
            borderRadius: 4,
            border: "1.5px solid #999",
            appearance: "none",
            backgroundColor: "white",
            backgroundImage: `url('data:image/svg+xml;utf8,<svg fill="%23999" height="24" viewBox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M7 10l5 5 5-5z"/></svg>')`,
            backgroundRepeat: "no-repeat",
            backgroundPosition: "right 0.5rem center",
            backgroundSize: "1rem"
          }}
        >
          <option value="12">12 months</option>
          <option value="24">24 months</option>
          <option value="36">36 months</option>
        </select>

        <button
          type="submit"
          style={{
            padding: "0.75rem",
            fontSize: "1rem",
            borderRadius: 4,
            border: "none",
            backgroundColor: "#007bff",
            color: "white",
            cursor: "pointer"
          }}
        >
          Compute payment
        </button>
      </form>

      {error && (
        <p
          role="alert"
          style={{ color: "#b00020", marginTop: "1rem", fontWeight: "bold" }}
        >
          {error}
        </p>
      )}

      <section
        aria-label="Monthly payment result"
        style={{
          marginTop: "1.5rem",
          padding: "1rem",
          border: "1.5px solid #999",
          borderRadius: 4,
          minHeight: 72,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center"
        }}
      >
        <p style={{ margin: 0, fontSize: "1rem", color: "#555" }}>
          Monthly payment
        </p>
        <p style={{ margin: 0, fontSize: "1.5rem", fontWeight: "bold" }}>
          ${monthlyPayment === null ? "0" : monthlyPayment}
        </p>
      </section>
    </main>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

